/** Zusätzliche Glossarbegriffe dieser Klasse: {id:{name,short,long}} – werden in GLOSSARY gemischt (vorhandene: augen, blatt,
 *  stich, farbebedienen, abrechnen in content/resources.js). Zahlen aus RESOURCES.kaethe und BALANCE. */
const C=RESOURCES.kaethe,W=BALANCE.procs.defaultWindow,nice=v=>String(v).replace('.',','),m=u=>nice(Math.round(u/8*10)/10);
export const GLOSSARY_KAETHE={
 grand:{name:'Grand',short:'Vier Buben in einem Spiel: Abrechnen trifft anderthalbfach und alle Gegner ringsum.',
  long:'Nur mit der Grand-Spielerin als Hauptbaum. Zwischen zwei Abrechnen zählen alle ausgespielten Buben mit; ab dem vierten zeigt die Leiste GRAND. Dann trifft Abrechnen anderthalbfach und nicht nur das Ziel, sondern alle Gegner im Umkreis – zusätzlich zu Schneider und Schwarz. Neu geben bringt sicher einen Buben, Talente bringen mehr.'},
 schneider:{name:'Schneider',short:'Ab '+C.schneider+' Augen trifft Abrechnen stärker – wer weiterzockt statt abzurechnen, wird belohnt.',
  long:`Ein Spiel ist ab ${C.win} Augen gewonnen, ab ${C.schneider} Augen Schneider: Abrechnen trifft dann ×${nice(C.abrechnen.schneider)}. Wer statt bei ${C.win} weiterzockt, riskiert, dass der Kampf vorher endet – außerhalb des Kampfes verfallen die Augen nach ${C.forget} s.`},
 schwarz:{name:'Schwarz',short:'Bei '+C.schwarz+' Augen ist der Block voll: Abrechnen trifft doppelt und alle Gegner ringsum.',
  long:`Mehr geht nicht: bei ${C.schwarz} Augen trifft Abrechnen ×${nice(C.abrechnen.schwarz)} und zusätzlich alle Gegner im Umkreis von ${m(C.abrechnen.radius)} m. Schwarz schafft nur, wer Buben, Stiche und Reizen zusammenbringt und lange genug nicht abrechnet.`},
 bube:{name:'Bube',short:'Der Trumpf im Blatt: bedient jede Farbe und sticht jeden Gegnerzauber.',
  long:`Vier Buben liegen im Blatt, einer je Farbe. Ein Bube wirkt nach seiner Farbe mit ×${nice(C.ranks.B.power)}, zählt ${C.ranks.B.augen} Augen (dazu ${C.augenPerCard} je Karte), verlängert jede Farbkette und sticht jede Gegnerkarte. Neu geben legt dir sicher einen Buben in die neue Hand. Am Stammtisch heißt der Kreuz-Bube „der Alte“.`},
 luschen:{name:'Luschen',short:'Sieben, Acht und Neun: schwach und ohne eigene Augen, aber schnell gespielt.',
  long:`Luschen wirken nur ×${nice(C.ranks[7].power)} bis ×${nice(C.ranks[9].power)} und zählen keine eigenen Augen – nur die ${C.augenPerCard} Grundaugen jeder Karte. Dafür sperren sie die globale Abklingzeit nur ${nice(BALANCE.player.gcdMin)} s statt ${nice(BALANCE.player.gcdBase)} s. Eine Hand voller Luschen ist langsamer, aber nie nutzlos.`},
 ouvert:{name:'Ouvert',short:'Offen gespielt: die nächste Karte des Stapels liegt sichtbar über deiner Hand.',
  long:'Beim Skat heißt ouvert, dass die Karten offen auf dem Tisch liegen. Bei Käthe zeigt die Anzeige über der Hand, welche Karte als Nächstes nachrückt. Die Kartenlegerin kann das von Haus aus, alle anderen lernen es über Talente. Wer die nächste Karte kennt, weiß, welche Karte jetzt raus muss.'},
 nullouvert:{name:'Null ouvert',short:'Skatspiel ohne einen einzigen Stich, Karten offen – bei Käthe der Pfad der kleinen, schnellen Karten.',
  long:'Beim Null ouvert gewinnt, wer keinen Stich macht, und alle sehen die Karten. Der Pfad der Grand-Spielerin mit diesem Namen macht Luschen stark und schnell, legt mehr Karten auf die Hand und belohnt den Kartenregen und das schnelle Durchspielen der Hand.'},
 kontra:{name:'Kontra',short:'Käthes Unterbrechen – hältst du die Farbe der Gegnerkarte, zählt es zusätzlich als Stich.',
  long:`Kontra! bricht einen gelben Zauber ab wie jedes Unterbrechen. Hältst du dabei eine Karte in der Farbe der Gegnerkarte, zählt es auch als Stich: die Augen der Gegnerkarte plus ${C.stich.bonus}. Am Skattisch verdoppelt Kontra das Spiel; die Antwort darauf heißt Re, danach wird Bock gespielt.`},
 bock:{name:'Bockrunde',short:'Doppelt gesetzt: ein kurzes Fenster, in dem der nächste Einsatz doppelt wirkt – wie die Bockrunde am Skattisch.',
  long:`Am Skattisch folgt auf Kontra das Re und danach die Bockrunde, in der alles doppelt zählt. Bei Käthe öffnen die Talente von Re und Bock ein Fenster von ${W} s: die genannte Karte oder das nächste Abrechnen wirkt doppelt. Wer das Fenster verstreichen lässt, verschenkt den Einsatz.`},
 aermel:{name:'Ass im Ärmel',short:'Ein zusätzlicher Kartenplatz der Falschspielerin für eine zurückgehaltene Karte.',
  long:'Nur mit der Falschspielerin als Hauptbaum. Der Kniff Ass im Ärmel legt die erste Karte der Hand in den Ärmel oder spielt die Ärmelkarte aus. Dort wartet sie, bis ein Gegnerzauber genau ihre Farbe verlangt – dann sticht sie sicher, statt vom Zufall der Hand abzuhängen.'},
 handspiel:{name:'Handspiel',short:'Beim Skat: ohne den Skat aufzunehmen spielen. Bei Käthe: nach dem Abrechnen ohne Pause weiter.',
  long:'Wer beim Skat Hand spielt, verzichtet auf die zwei Karten im Skat und zählt dafür mehr. Bei Käthe tragen die Schlusssteine Grand Hand und Null ouvert Hand diesen Namen: nach dem Abrechnen geht es ohne Pause mit frischen Karten weiter, statt erst neu zu sammeln.'},
 ramsch:{name:'Ramsch',short:'Skatrunde, in der keiner reizt und jeder möglichst wenig Augen will – außer beim Durchmarsch.',
  long:'Beim Ramsch schiebt jeder seine Karten weiter, und wer am Ende die meisten Augen hat, verliert. Wer dagegen alle Stiche macht, schafft den Durchmarsch und gewinnt alles. Bei Käthe steht der Durchmarsch für den Kartenregen, der die ganze Hand auf einmal auf den Tisch wirft.'},
 legekreis:{name:'Legekreis',short:'Der Kartenregen der Kartenlegerin: ein Kreis aus Karten, der eine Weile alle darin heilt.',
  long:'Nur mit der Kartenlegerin als Hauptbaum. Die ganze Hand wird im Kreis auf einen freien Bodenpunkt gelegt; acht Sekunden lang heilt der Kreis alle darin, jede Karte wirkt einmal nach ihrer Farbe, danach ziehst du neu. Leg ihn dorthin, wo die Gruppe gleich steht.'}
};
